actions.script:
const toNumber = (value) => value == null || value === '' ? null : Number(value)
// :name values as JSON; text that is not JSON is the caller's error, answered as one
let parameters = null
try { parameters = context.parametersJson ? JSON.parse(String(context.parametersJson)) : null }
catch (e) { ec.web.sendJsonResponse({errors: ec.l10n.localize('The parameters are not JSON: ') + String(e.message || e)}); return }
const out = ec.service.sync().name('org.moqui.dev.DatabaseServices.run#Sql').parameters({db, sqlText: String(ec.web.secureRequestParameters.sqlText || ''), parameters,
    allowChanges: String(context.allowChanges) == 'true', token: context.token || null, confirmDatabaseName: context.confirmDatabaseName || null,
    eachOnOwn: String(context.eachOnOwn) == 'true', limit: toNumber(context.limit), offset: toNumber(context.offset),
    timeoutSeconds: toNumber(context.timeoutSeconds), runId: context.runId || null}).call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse(Object.assign({}, out, {errors}))

const toNumber = (value) => value == null || value === '' ? null : Number(value)
// :name values as JSON; text that is not JSON is the caller's error, answered as one
let parameters = null
try { parameters = context.parametersJson ? JSON.parse(String(context.parametersJson)) : null }
catch (e) { ec.web.sendJsonResponse({errors: ec.l10n.localize('The parameters are not JSON: ') + String(e.message || e)}); return }
const out = ec.service.sync().name('org.moqui.dev.DatabaseServices.explain#Sql').parameters({db, sqlText: String(ec.web.secureRequestParameters.sqlText || ''), parameters,
    analyze: String(context.analyze) == 'true', token: context.token || null, confirmDatabaseName: context.confirmDatabaseName || null,
    runId: context.runId || null, timeoutSeconds: toNumber(context.timeoutSeconds)}).call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
// a plan not run (no ANALYZE) says nothing of the rows a seq scan reads: the catalog's estimates of the tables
// (get#TableStats) mark one over 10,000
let relationRows = null
if (!errors && !out.analyzed && out.format == 'json') {
    const stats = ec.service.sync().name('org.moqui.dev.DatabaseServices.get#TableStats').parameters({db}).call() || {}
    ec.message.clearErrors()
    relationRows = {}
    for (const table of stats.tables || []) if (table.table_name) relationRows[String(table.table_name).toLowerCase()] = table.estimated_rows
}
ec.web.sendJsonResponse(Object.assign({}, out, {errors, relationRows}))

const out = ec.service.sync().name('org.moqui.dev.DatabaseServices.store#SavedQuery').parameters({queryId: context.queryId || null, description: context.description || null, db, sqlText: String(ec.web.secureRequestParameters.sqlText || ''),
    isShared: String(context.isShared) == 'true', parametersJson: context.parametersJson || null}).call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse(Object.assign({}, out, {errors}))
